def otherside_rightangle(a, b):
    # If both inputs are legs, the missing side is the hypotenuse.
    # Otherwise, infer the hypotenuse from the larger side and compute the remaining leg.
    if a <= 0 or b <= 0:
        raise ValueError("Sides must be positive")

    if a == b:
        return math.sqrt(a * a + b * b)

    hypotenuse = max(a, b)
    side = min(a, b)

    diff = hypotenuse * hypotenuse - side * side
    if diff < 0 and diff > -1e-12:
        diff = 0.0
    return math.sqrt(diff)

