def max_sum_increasing_subseq(a, n, index, k):
    # dp[j] = maximum sum of increasing subsequence ending at j
    dp = [0] * n

    for i in range(index + 1):
        dp[i] = a[i]
        for j in range(i):
            if a[j] < a[i] and dp[j] + a[i] > dp[i]:
                dp[i] = dp[j] + a[i]

